import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] allSums(long[] a, int from, int to) {
        long[] v = new long[1 << (to - from)];
        int size = 1;
        for (int i = from; i < to; i++) {
            for (int k = 0; k < size; k++) v[size + k] = v[k] + a[i];
            size *= 2;
        }
        Arrays.sort(v);
        return v;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long t = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cn = (int) n;
        int h = cn / 2;
        long[] lhs = allSums(a, 0, h);
        long[] rhs = allSums(a, h, cn);
        long count = 0;
        int j = rhs.length;
        for (long s : lhs) {
            while (j > 0 && s + rhs[j - 1] > t) j--;
            if (j == 0) break;
            count += j;
        }
        System.out.println(count);
    }
}
